solution.python:
from typing import List


class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        def valid(candidate: str) -> bool:
            balance = 0
            for ch in candidate:
                if ch == '(':
                    balance += 1
                elif ch == ')':
                    balance -= 1
                    if balance < 0:
                        return False
            return balance == 0

        level = {s}
        while level:
            answers = sorted(candidate for candidate in level if valid(candidate))
            if answers:
                return answers

            next_level = set()
            for candidate in level:
                for i, ch in enumerate(candidate):
                    if ch not in '()':
                        continue
                    if i > 0 and candidate[i] == candidate[i - 1]:
                        continue
                    next_level.add(candidate[:i] + candidate[i + 1:])
            level = next_level

        return [""]
